  tabular?: boolean;
}

export function Text({ variant = 'body', emphasized = false, tone = 'primary', as = 'p', tabular = false, className, ...props }: TextProps) {
  return createElement(as, {
    ...props,
    'data-variant': variant,
    'data-tone': tone,
    'data-emphasized': emphasized ? 'true' : undefined,
    'data-tabular': tabular ? 'true' : undefined,
    className: cx('lg-text', className),
  });
}

'use client';
import type { HTMLAttributes, ReactNode } from 'react';
import { cx } from '../system/utils.js';

export interface GlassBadgeProps extends Omit<HTMLAttributes<HTMLSpanElement>, 'children'> {
  /** A count, or text for a status badge. Counts above `max` render as "max+". */
  count?: number;
  max?: number;
  children?: ReactNode;
  tone?: 'notification' | 'neutral' | 'accent';
  /** A bare dot, for "something changed" with no useful number. */
  dot?: boolean;
  /**
   * Badges are read out on their own, so say what the number means. Without this a screen
   * reader announces a naked "3".
   */
  'aria-label'?: string;
}

/**
 * Colour alone never carries the meaning here: the badge always contains a number or a
 * label, and the accessible name spells out what it counts.
 */
export function GlassBadge({ count, max = 99, children, tone = 'notification', dot = false, className, ...props }: GlassBadgeProps) {
  const text = dot ? null : children ?? (count === undefined ? null : count > max ? `${max}+` : String(count));
  if (!dot && (text === null || text === '')) return null;
  return <span {...props} className={cx('lg-badge', className)} data-tone={tone} data-dot={dot ? 'true' : undefined}>{text}</span>;
}

'use client';
import { forwardRef, type ButtonHTMLAttributes } from 'react';
import { useGlassSurface, type GlassSurfaceOptions } from '../system/material.js';
import { useSharedSurface } from '../system/surface.js';
import { cx } from '../system/utils.js';

/**
 * Style — not size — is what marks the preferred option, and a view should carry at most
 * one prominent button. Everything else stays regular, or the emphasis means nothing.
 *
 * `glass` / `glassProminent` are the floating control-layer styles. `plain`, `gray` and
 * `tinted` are flat and belong wherever a button sits *in* content rather than above it.
 */
export type GlassButtonVariant =
  | 'glass' | 'glassProminent' | 'plain' | 'gray' | 'tinted' | 'destructive' | 'destructiveProminent';
/** Control heights. `small` keeps a 44pt hit region on touch via padding, not a smaller target. */
export type ControlSize = 'small' | 'regular' | 'large' | 'extraLarge';

export interface GlassButtonProps extends ButtonHTMLAttributes<HTMLButtonElement>, GlassSurfaceOptions {
  variant?: GlassButtonVariant;
  /** Visual height of the control. Distinct from `size`, which selects the glass thickness. */
  controlSize?: ControlSize;
  loading?: boolean;
  /** Keep this button's own glass even inside a shared surface. Use sparingly — it is glass on glass. */
  independent?: boolean;
}

const GLASSY = new Set<GlassButtonVariant>(['glass', 'glassProminent']);

export const GlassButton = forwardRef<HTMLButtonElement, GlassButtonProps>(function GlassButton(
  { material, backdropTone, density, renderer, radius = 'pill', refraction, size, chroma,
    className, style, children, variant = 'glass', controlSize = 'regular', loading = false, disabled,
    independent = false, type = 'button', ...props }, ref,
) {
  const shared = useSharedSurface();
  // Flat variants never grow their own glass, and inside a shared surface neither does anything
  // else: the group is the glass, the children are items on it.
  const flat = !GLASSY.has(variant);
  const glass = useGlassSurface({ material, backdropTone, density, renderer, radius, refraction, size, chroma }, ref, (shared && !independent) || flat, true);
  return <button {...props} ref={glass.ref} type={type} disabled={disabled || loading} aria-busy={loading || undefined}
    {...glass.attributes} data-variant={variant} data-control-size={controlSize}
    className={cx('lg-root lg-button', className)} style={{ ...glass.style, ...style }}>
    {glass.decoration}<span className="lg-content">{loading && <span className="lg-spinner" aria-hidden="true" />}{children}</span>
  </button>;
});

export interface GlassIconButtonProps extends GlassButtonProps {
  /** Icon-only controls carry no visible text, so the accessible name is mandatory. */
  'aria-label': string;
}
export const GlassIconButton = forwardRef<HTMLButtonElement, GlassIconButtonProps>(function GlassIconButton({ className, ...props }, ref) {
  return <GlassButton {...props} ref={ref} className={cx('lg-icon-button', className)} />;
});

'use client';
import type { CSSProperties } from 'react';
import { cx } from '../system/utils.js';
import { clamp } from '../../core/index.js';

export interface GlassProgressProps {
  /** Omit for an indeterminate indicator. Provide it as soon as the duration is known. */
  value?: number;
  total?: number;
  'aria-label': string;
  /** `bar` for a known task, `circular` for a short indefinite wait. */
  variant?: 'bar' | 'circular';
  className?: string;
}

/**
 * Determinate whenever the duration is known — an indeterminate spinner tells the user
 * nothing except that the app is still alive. Never blocks the interface: show content as
 * soon as any of it exists, and prefer a skeleton that matches the final layout over a
 * spinner in the middle of an empty page.
 */
export function GlassProgress({ value, total = 100, 'aria-label': label, variant = 'bar', className }: GlassProgressProps) {
  if (!Number.isFinite(total) || total <= 0) throw new RangeError('GlassProgress requires total > 0');
  const determinate = Number.isFinite(value);
  const fraction = determinate ? clamp(value! / total, 0, 1) : 0;
  const aria = determinate
    ? { 'aria-valuenow': Math.round(fraction * 100), 'aria-valuemin': 0, 'aria-valuemax': 100 }
    : {};
  return <div role="progressbar" aria-label={label} {...aria}
    className={cx('lg-progress', className)} data-variant={variant} data-determinate={determinate ? 'true' : 'false'}
    style={{ '--lg-progress': fraction } as CSSProperties}>
    {variant === 'bar'
      ? <span className="lg-progress-track"><span className="lg-progress-fill" /></span>
      : <span className="lg-progress-ring" />}
  </div>;
}

'use client';
import { useEffect, useId, useRef, useState, type CSSProperties, type ReactNode, type RefObject } from 'react';
import { GlassSurface } from '../system/surface.js';
import { type GlassSurfaceOptions } from '../system/material.js';
import { cx, useControllable } from '../system/utils.js';
import { usePull, elementAt } from '../system/pull.js';
import { useFusion } from '../system/fusion.js';
import { useGlassPolicy } from '../system/provider.js';

export interface GlassChoice { value: string; label: ReactNode; disabled?: boolean }

/** Lens centre with its live pull offset removed: when the selection changes mid-drag the lens glides to the new slot while the offset eases to zero. */
export function lensOrigin(lens: HTMLElement | null) {
  if (!lens) return null;
  const box = lens.getBoundingClientRect();
  const shiftX = parseFloat(lens.style.getPropertyValue('--lg-shift-x')) || 0;
  const shiftY = parseFloat(lens.style.getPropertyValue('--lg-shift-y')) || 0;
  return { x: box.left + box.width / 2 - shiftX, y: box.top + box.height / 2 - shiftY };
}

/**
 * Measures the selected child and positions a single shared lens that glides between choices.
 *
 * Both axes are tracked, not just the horizontal one: the same lens has to follow a row of
 * segments and a vertical column of sidebar rows, and a column's items all share `offsetLeft`.
 */
export function useSelectionLens<T extends HTMLElement>(root: RefObject<T | null>, selector: string, deps: unknown[]) {
  const [lens, setLens] = useState<CSSProperties>({ opacity: 0 });
  useEffect(() => {
    const node = root.current; if (!node) return;
    const update = () => {
      const target = node.querySelector<HTMLElement>(selector);
      if (target) setLens({
        width: target.offsetWidth, height: target.offsetHeight,
        transform: `translate(${target.offsetLeft}px, ${target.offsetTop}px)`,
        opacity: 1,
      });
      else setLens({ opacity: 0 });
    };
    update(); const observer = new ResizeObserver(update); observer.observe(node);
    if (typeof document !== 'undefined' && 'fonts' in document) document.fonts.ready.then(update, () => {});
    return () => observer.disconnect();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [root, selector, ...deps]);
  return lens;
}

export interface GlassSegmentedControlProps extends GlassSurfaceOptions {
  items: GlassChoice[]; value?: string; defaultValue?: string; onValueChange?: (value: string) => void;
  'aria-label': string; name?: string; disabled?: boolean; className?: string;
}

/**
 * Two to five equal-width segments, text **or** icons but never both mixed. Native radio
 * inputs underneath provide form participation and arrow-key selection.
 *
 * It is a scrubber, not a row of buttons: press the selected segment and slide, and the lens
 * tracks the pointer 1:1, stretches with the drag and updates the selection *live* as it
 * crosses each segment, settling on a spring. This is the interaction most often missing
 * from imitations of the system control.
 */
export function GlassSegmentedControl({ items, value, defaultValue, onValueChange, name, disabled, className, 'aria-label': label, ...surface }: GlassSegmentedControlProps) {
  const id = useId();
  const [selected, setSelected] = useControllable(value, defaultValue ?? items.find(x => !x.disabled)?.value ?? '', onValueChange);
  const root = useRef<HTMLDivElement>(null);
  const policy = useGlassPolicy();
  const lens = useSelectionLens(root, '.lg-segment:has(input:checked)', [selected, items]);
  const lensRef = useRef<HTMLSpanElement>(null);
  const fusion = useFusion(root, { itemSelector: '.lg-segment:not([data-disabled="true"])', lensSelector: '.lg-selection-lens' });
  usePull(root, {
    axis: 'x', limit: 18, stretch: .8,
    targets: () => lensRef.current ? [lensRef.current] : [],
    origin: () => lensOrigin(lensRef.current),
    disabled: event => !!disabled || !!(event.target as HTMLElement).closest('[data-disabled="true"]'),
    onPress: event => pick(event), onMove: event => pick(event),
  }, !policy.reduceMotion && !disabled);
  function pick(event: PointerEvent) {
    const hit = elementAt(event, '.lg-segment'); const input = hit?.querySelector<HTMLInputElement>('input');
    if (input && !input.disabled && input.value !== selected && root.current?.contains(input)) setSelected(input.value);
  }
  return <GlassSurface {...surface} radius={surface.radius ?? 'pill'} className={cx('lg-segmented', className)}>
    <div className="lg-segmented-track" ref={root} role="radiogroup" aria-label={label}>
      {fusion}<span aria-hidden="true" className="lg-selection-lens" ref={lensRef} style={lens} />
      {items.map(item => <label key={item.value} className="lg-segment" data-disabled={disabled || item.disabled ? 'true' : 'false'}>
        <input type="radio" name={name ?? `segment-${id}`} value={item.value} checked={selected === item.value} disabled={disabled || item.disabled} onChange={() => setSelected(item.value)} />
        <span>{item.label}</span>
      </label>)}
    </div>
  </GlassSurface>;
}

'use client';
import { useRef, type CSSProperties } from 'react';
import { usePull } from '../system/pull.js';
import { useGlassSurface, type GlassSurfaceOptions } from '../system/material.js';
import { useGlassPolicy } from '../system/provider.js';
import { cx, useControllable } from '../system/utils.js';
import { clamp } from '../../core/index.js';

export interface GlassSliderProps extends GlassSurfaceOptions {
  value?: number; defaultValue?: number; onValueChange?: (value: number) => void;
  min?: number; max?: number; step?: number; disabled?: boolean; name?: string;
  'aria-label': string;
  /** Spoken value when the bare number is ambiguous — "62 percent", "4 of 10". */
  formatValue?: (value: number) => string;
  /** Glyphs at the ends of the track, e.g. a small and a large speaker. */
  minLabel?: React.ReactNode; maxLabel?: React.ReactNode;
  className?: string;
}

/**
 * A real `<input type="range">` under a drawn track and knob. Rebuilding the input would
 * cost keyboard support, form participation and `aria-valuetext` for nothing.
 *
 * The knob is quiet at rest and **lifts into glass only while it is being manipulated** —
 * a transient control in the content layer, per the Liquid Glass rules. A knob that is
 * permanently glass is glass in the content layer.
 */
export function GlassSlider({ value, defaultValue = 50, onValueChange, min = 0, max = 100, step = 1, disabled, name, 'aria-label': label, formatValue, minLabel, maxLabel, className, ...surface }: GlassSliderProps) {
  if (![min, max, step].every(Number.isFinite) || min >= max || step <= 0) throw new RangeError('GlassSlider requires finite min < max and step > 0');
  const [current, setCurrent] = useControllable(value, defaultValue, onValueChange);
  const safe = clamp(Number.isFinite(current) ? current : min, min, max), progress = (safe - min) / (max - min);
  const root = useRef<HTMLDivElement>(null);
  const policy = useGlassPolicy();
  // The knob keeps its glass machinery mounted so the displacement texture is not rebuilt on
  // every press; CSS decides whether that machinery is visible.
  const knob = useGlassSurface<HTMLSpanElement>({ ...surface, radius: 'pill' });
  usePull(root, {
    limit: 10, stretch: 1,
    targets: () => knob.root.current ? [knob.root.current] : [],
    // Horizontal motion is the value itself; only vertical pull stretches the knob, horizontal shows the lag.
    origin: () => { const box = knob.root.current?.getBoundingClientRect(); return box ? { x: box.left + box.width / 2, y: box.top + box.height / 2 } : null; },
    disabled: () => !!disabled,
  }, !policy.reduceMotion);
  return <div ref={root} className={cx('lg-slider', className)} data-disabled={disabled ? 'true' : 'false'} style={{ '--lg-progress': progress } as CSSProperties}>
    {minLabel && <span className="lg-slider-edge" aria-hidden="true">{minLabel}</span>}
    <span className="lg-slider-rail">
      <span className="lg-slider-track" aria-hidden="true"><span className="lg-slider-fill" /></span>
      <span ref={knob.ref} {...knob.attributes} className="lg-root lg-slider-lens" style={knob.style} aria-hidden="true">{knob.decoration}</span>
      <input type="range" aria-label={label} aria-valuetext={formatValue?.(safe)} min={min} max={max} step={step} value={safe} disabled={disabled} name={name}
        onChange={event => setCurrent(Number(event.currentTarget.value))} />
    </span>
    {maxLabel && <span className="lg-slider-edge" aria-hidden="true">{maxLabel}</span>}
  </div>;
}

'use client';
import { cx, useControllable } from '../system/utils.js';
import { LibraryIcon } from '../system/icon.js';
import { clamp } from '../../core/index.js';

export interface GlassStepperProps {
  value?: number; defaultValue?: number; onValueChange?: (value: number) => void;
  min?: number; max?: number; step?: number; disabled?: boolean;
  'aria-label': string;
  /** Spoken and displayed form of the value. The number alone is rarely enough. */
  formatValue?: (value: number) => string;
  /** Render the value inside the control. Off when the value already appears next to it in a row. */
  showValue?: boolean;
  decrementLabel?: string;
  incrementLabel?: string;
  className?: string;
}

/**
 * Two segments sharing one surface, for small integer ranges only — past a handful of taps
 * a slider or a field is the honest control. The value is always visible, either inside the
 * stepper or immediately beside it.
 */
export function GlassStepper({
  value, defaultValue = 0, onValueChange, min = -Infinity, max = Infinity, step = 1, disabled,
  'aria-label': label, formatValue, showValue = true, decrementLabel = 'Decrease', incrementLabel = 'Increase', className,
}: GlassStepperProps) {
  if (!Number.isFinite(step) || step <= 0) throw new RangeError('GlassStepper requires step > 0');
  if (min >= max) throw new RangeError('GlassStepper requires min < max');
  const [current, setCurrent] = useControllable(value, defaultValue, onValueChange);
  const safe = clamp(Number.isFinite(current) ? current : 0, min, max);
  const shown = formatValue ? formatValue(safe) : String(safe);
  const nudge = (direction: 1 | -1) => setCurrent(clamp(safe + direction * step, min, max));
  return <div className={cx('lg-stepper', className)} role="group" aria-label={label} data-disabled={disabled ? 'true' : undefined}>
    <button type="button" className="lg-stepper-button" aria-label={decrementLabel} disabled={disabled || safe <= min} onClick={() => nudge(-1)}>
      <LibraryIcon name="minus" size={18} />
    </button>
    {showValue && <output className="lg-stepper-value" aria-live="off">{shown}</output>}
    <button type="button" className="lg-stepper-button" aria-label={incrementLabel} disabled={disabled || safe >= max} onClick={() => nudge(1)}>
      <LibraryIcon name="plus" size={18} />
    </button>
  </div>;
}

'use client';
import { useId, useRef } from 'react';
import { usePull } from '../system/pull.js';
import { useGlassSurface, type GlassSurfaceOptions } from '../system/material.js';
import { cx, useControllable } from '../system/utils.js';

export interface GlassSwitchProps extends GlassSurfaceOptions {
  checked?: boolean; defaultChecked?: boolean; onCheckedChange?: (checked: boolean) => void;
  disabled?: boolean; name?: string;
  /** Describe the **on** state — "Wi-Fi", not "Enable Wi-Fi" and never "Enable/Disable". */
  'aria-label': string;
  label?: string;
  className?: string;
}

/**
 * A capsule toggle, green when on, over a real `<input type="checkbox" role="switch">`.
 *
 * It is a drag target as well as a tap target: throw the knob and it lands on the nearer
 * side, tracking the pointer 1:1 and stretching along the drag before it springs. A
 * click-only switch is one of the clearest tells that an interface is not Apple's.
 */
export function GlassSwitch({ checked, defaultChecked = false, onCheckedChange, disabled, name, 'aria-label': label, label: visibleLabel, className, ...surface }: GlassSwitchProps) {
  const id = useId();
  const [active, setActive] = useControllable(checked, defaultChecked, onCheckedChange);
  const glass = useGlassSurface<HTMLSpanElement>({ ...surface, radius: 'pill' });
  const thumb = useRef<HTMLSpanElement>(null); const dragged = useRef(false); const labelRef = useRef<HTMLLabelElement>(null);
  usePull(labelRef, {
    axis: 'x', limit: 14, stretch: 1.2,
    targets: () => [thumb.current!, glass.root.current!].filter(Boolean) as HTMLElement[],
    disabled: () => !!disabled,
    onRelease: ({ dx, cancelled }) => {
      if (cancelled || Math.abs(dx) < 6) { dragged.current = false; return; }
      // A deliberate drag decides by direction and suppresses the label's synthetic click.
      dragged.current = true; const next = dx > 0; if (next !== active) setActive(next);
    },
  }, !glass.policy.reduceMotion);
  return <label ref={labelRef} className={cx('lg-switch', className)} data-disabled={disabled ? 'true' : 'false'} htmlFor={id}
    onClickCapture={event => { if (dragged.current) { dragged.current = false; event.preventDefault(); event.stopPropagation(); } }}>
    <input id={id} type="checkbox" role="switch" aria-label={label} name={name} checked={active} disabled={disabled} onChange={event => setActive(event.currentTarget.checked)} />
    <span ref={glass.ref} {...glass.attributes} className="lg-root lg-switch-track" data-checked={active ? 'true' : 'false'} style={glass.style} aria-hidden="true">
      {glass.decoration}<span className="lg-switch-thumb" ref={thumb} />
    </span>{visibleLabel && <span className="lg-switch-label">{visibleLabel}</span>}
  </label>;
}

'use client';
import { forwardRef, useId, useRef, type InputHTMLAttributes } from 'react';
import { cx, useControllable, useMergedRef } from '../system/utils.js';
import { LibraryIcon } from '../system/icon.js';
import { useGlassSurface, type GlassSurfaceOptions } from '../system/material.js';

export interface SearchFieldProps extends Omit<InputHTMLAttributes<HTMLInputElement>, 'value' | 'defaultValue' | 'onChange' | 'size' | 'type'>, GlassSurfaceOptions {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onSubmitQuery?: (value: string) => void;
  'aria-label': string;
  clearLabel?: string;
  className?: string;
}

/**
 * A capsule search field on its own glass surface — top-trailing on wide layouts, and on a
 * phone either the trailing search tab or a field that rises with the keyboard.
 *
 * `type="search"` gives the right on-screen keyboard and the platform's own clear gesture;
 * the drawn clear button is the pointer affordance on top of that. The focus ring lands on
 * the glass container via `:focus-within`, because the input's own outline is suppressed and
 * something has to replace it.
 */
export const SearchField = forwardRef<HTMLInputElement, SearchFieldProps>(function SearchField(
  { value, defaultValue = '', onValueChange, onSubmitQuery, 'aria-label': label, clearLabel = 'Clear search',
    className, material, backdropTone, density, renderer, radius, refraction, size, chroma, ...props }, ref,
) {
  const id = useId();
  const [query, setQuery] = useControllable(value, defaultValue, onValueChange);
  const [input, mergedRef] = useMergedRef<HTMLInputElement>(ref);
  const glass = useGlassSurface<HTMLDivElement>({ material, backdropTone, density, renderer, radius: radius ?? 'pill', refraction, size, chroma });
  const form = useRef<HTMLFormElement>(null);
  return <form ref={form} role="search" className={cx('lg-search', className)} onSubmit={event => { event.preventDefault(); onSubmitQuery?.(query); }}>
    <div ref={glass.ref} {...glass.attributes} className="lg-root lg-search-box" style={glass.style}>
      {glass.decoration}
      <div className="lg-content">
        <LibraryIcon name="search" size={17} className="lg-search-icon" />
        <input {...props} ref={mergedRef} id={`${id}-search`} type="search" aria-label={label} className="lg-search-input"
          value={query} onChange={event => setQuery(event.currentTarget.value)} />
        {query !== '' && <button type="button" className="lg-search-clear" aria-label={clearLabel}
          onClick={() => { setQuery(''); input.current?.focus(); }}>
          <LibraryIcon name="clear" size={17} />
        </button>}
      </div>
    </div>
  </form>;
});

'use client';
import { forwardRef, useId, type InputHTMLAttributes, type ReactNode } from 'react';
import { cx } from '../system/utils.js';
import { Text } from '../content/text.js';

export interface TextFieldProps extends Omit<InputHTMLAttributes<HTMLInputElement>, 'size'> {
  /** A real, visible label. A placeholder is a hint about the format, never a substitute. */
  label: ReactNode;
  /** Supporting text shown under the field. Announced with the input. */
  hint?: ReactNode;
  /**
   * Error text. Presence marks the field invalid and wires up `aria-describedby`, so the
   * meaning never rests on a red border alone.
   */
  error?: ReactNode;
  leading?: ReactNode;
  trailing?: ReactNode;
  /** Hide the label visually but keep it for assistive technology and Voice Control. */
  labelHidden?: boolean;
}

/**
 * A rounded text field with a real `<label for>`.
 *
 * The details that make a web form feel native are all here and all easy to forget:
 * `autocomplete` and `inputmode` should be set by the caller for the field's purpose,
 * the font-size stays at 16px or above so iOS Safari does not zoom on focus, and the focus
 * ring is an `outline` on the container rather than a `box-shadow`.
 */
export const TextField = forwardRef<HTMLInputElement, TextFieldProps>(function TextField(
  { label, hint, error, leading, trailing, labelHidden = false, className, id, type = 'text', ...props }, ref,
) {
  const generated = useId();
  const fieldId = id ?? `${generated}-field`;
  const hintId = hint ? `${generated}-hint` : undefined;
  const errorId = error ? `${generated}-error` : undefined;
  const describedBy = [errorId, hintId].filter(Boolean).join(' ') || undefined;
  return <div className={cx('lg-field', className)} data-invalid={error ? 'true' : undefined}>
    <Text as="label" variant="subhead" emphasized className={cx('lg-field-label', labelHidden && 'lg-visually-hidden')} {...{ htmlFor: fieldId }}>{label}</Text>
    <div className="lg-field-box">
      {leading && <span className="lg-field-leading" aria-hidden="true">{leading}</span>}
      <input {...props} ref={ref} id={fieldId} type={type} className="lg-field-input"
        aria-invalid={error ? true : undefined} aria-describedby={describedBy} />
      {trailing && <span className="lg-field-trailing">{trailing}</span>}
    </div>
