export interface NavigationBarProps {
  title: string;
  /** Controls at the leading edge — a back affordance, a menu. */
  leading?: ReactNode;
  /** Controls at the trailing edge. Group them by function; the primary action stands alone. */
  trailing?: ReactNode;
  /**
   * Show the large title in the content flow. Turn it off for secondary screens, which use
   * the compact title from the start.
   */
  largeTitle?: boolean;
  /** Subtitle shown under the large title only; the compact bar stays to one line. */
  subtitle?: ReactNode;
  'aria-label'?: string;
  className?: string;
  children?: ReactNode;
}

/**
 * A large title that hands over to a compact one as it scrolls away.
 *
 * The compact title is hidden while the large title is still on screen — showing both means
 * the same words twice, which is the most common way this pattern is misread. The bar itself
 * carries no background, border or shadow of its own: separation comes from the glass of the
 * control groups inside it and from the scroll edge effect beneath.
 */
export function NavigationBar({ title, leading, trailing, largeTitle = true, subtitle, 'aria-label': label, className, children }: NavigationBarProps) {
  const [compact, setCompact] = useState(!largeTitle);
  const sentinel = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!largeTitle) { setCompact(true); return; }
    const node = sentinel.current;
    if (!node || typeof IntersectionObserver === 'undefined') return;
    const observer = new IntersectionObserver(([entry]) => setCompact(!entry.isIntersecting), { threshold: 0 });
    observer.observe(node);
    return () => observer.disconnect();
  }, [largeTitle]);
  return <>
    <header className={cx('lg-navbar', className)} aria-label={label} data-compact={compact ? 'true' : undefined}>
      <div className="lg-navbar-leading">{leading}</div>
      {/* aria-hidden: the large title below is the real heading, so this must not duplicate it. */}
      <div className="lg-navbar-title" aria-hidden="true">{title}</div>
      <div className="lg-navbar-trailing">{trailing}</div>
    </header>
    {largeTitle && <div className="lg-largetitle">
      <Text as="h1" variant="largeTitle" emphasized>{title}</Text>
      {subtitle && <Text variant="subhead" tone="secondary">{subtitle}</Text>}
      <div ref={sentinel} className="lg-largetitle-sentinel" aria-hidden="true" />
    </div>}
    {children}
  </>;
}

'use client';
import { useEffect, useState, type RefObject } from 'react';
import { useGlassPolicy } from '../system/provider.js';
import { cx } from '../system/utils.js';

export interface ScrollEdgeProps {
  targetRef: RefObject<HTMLElement | null>;
  edge?: 'top' | 'bottom';
  /**
   * `soft` dissolves content progressively as it approaches the bar — the iOS default.
   * `hard` draws a uniform, more opaque boundary, which is what macOS uses for pinned column
   * headers and for controls that have no background of their own.
   */
  variant?: 'soft' | 'hard';
  /** Height of the dissolve in CSS px. Keep it consistent across the columns of a split view. */
  height?: number;
  className?: string;
}

/**
 * The scroll edge effect: what replaced opaque bar backgrounds and hairline dividers.
 *
 * It is not decoration and not a colour block — it exists only where content actually passes
 * beneath floating UI, and there is exactly one per scroll view. Use it instead of giving a
 * bar its own background: that is precisely the custom bar treatment the new design removes.
 */
export function ScrollEdge({ targetRef, edge = 'top', variant = 'soft', height = 44, className }: ScrollEdgeProps) {
  const [active, setActive] = useState(false);
  const policy = useGlassPolicy();
  useEffect(() => {
    const target = targetRef.current; if (!target) return;
    let frame = 0;
    const update = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => setActive(edge === 'top'
        ? target.scrollTop > 1
        : target.scrollTop + target.clientHeight < target.scrollHeight - 1));
    };
    const observer = new ResizeObserver(update); observer.observe(target);
    if (target.firstElementChild) observer.observe(target.firstElementChild);
    const mutation = new MutationObserver(update); mutation.observe(target, { childList: true, subtree: true, characterData: true });
    target.addEventListener('scroll', update, { passive: true }); update();
    return () => { observer.disconnect(); mutation.disconnect(); target.removeEventListener('scroll', update); cancelAnimationFrame(frame); };
  }, [targetRef, edge]);
  return <div aria-hidden="true" className={cx('lg-scroll-edge', className)} data-lg-theme={policy.resolvedTheme}
    data-edge={edge} data-variant={variant} data-active={active ? 'true' : 'false'}
    style={{ height: `${height}px` }} />;
}

